--
-- Name: hiring_job_update(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.hiring_job_update(p_ws uuid, p_id uuid, p_fields jsonb) RETURNS boolean
    LANGUAGE plpgsql
